use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserWebauthnCredentialEnabledAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserWebauthnCredentialEnabledAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that isEnabled returns null on a freshly created holder.
     */
    public function testEnabledNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserWebauthnCredentialEnabledAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isEnabledAssigned());
        $this->assertNull($holder->isEnabled());
    }
}
