    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedEnabledRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultEnabled();
    }
}
